<template><section class="space-y-5"><header class="flex items-end justify-between"><div><h1 class="text-2xl font-semibold">Lệnh điều xe</h1><p class="mt-1 text-sm text-muted-foreground">Theo dõi lệnh đã ban hành, chạy thực tế và hoàn thành.</p></div></header><DataGrid :data-source="source" :columns="columns" :pagination="{ mode: 'client', pageSize: 15, pageSizeOptions: [15,25,50] }" filter-row global-filter show-actions :get-row-id="row => String(row.id)" :persist="{ key: 'dispatch-orders', url: true }" empty-title="Chưa có lệnh điều xe" empty-description="Tạo lệnh từ lịch chuyến đã được phân công." @retry="query.refetch()"><template #actions="{ row }"><Button size="icon-xs" variant="ghost" title="Xem lệnh" @click="router.push({ name: 'dispatch-order-detail', params: { id: row.id } })"><Eye class="size-4" /></Button></template></DataGrid></section></template>
<script setup lang="ts">
import { useOrdersQuery } from '@/modules/dispatch/dispatch.composables'; import { formatDispatchDate, scheduleStatusLabel } from '@/modules/dispatch/dispatch.format'; import type { DispatchOrder } from '@/modules/dispatch/dispatch.types'; import { DataGrid, type DataGridColumnDef, type DataGridDataSource } from '@/shared/components/data-grid'; import { Button } from '@/shared/components/ui/button'; import { Eye } from '@lucide/vue'; import { computed } from 'vue'; import { useRouter } from 'vue-router'
const query = useOrdersQuery(); const router = useRouter(); const source = computed<DataGridDataSource<DispatchOrder>>(() => ({ data: query.data.value ?? [], isLoading: query.isLoading.value, isFetching: query.isFetching.value, error: query.error.value })); const columns: DataGridColumnDef<DispatchOrder>[] = [{ accessorKey: 'order_no', header: 'Mã lệnh', fixed: 'left', meta: { label: 'Mã lệnh' } }, { accessorKey: 'schedule_no', header: 'Lịch chuyến', meta: { label: 'Lịch chuyến' } }, { accessorKey: 'scheduled_start_at', header: 'Khởi hành', cell: ({ getValue }) => formatDispatchDate(String(getValue())), meta: { label: 'Khởi hành' } }, { accessorKey: 'customer_name', header: 'Khách', meta: { label: 'Khách' } }, { id: 'vehicle', header: 'Xe / tài xế', cell: ({ row }) => `${row.original.assignment?.license_plate ?? '—'} · ${row.original.assignment?.driver_name ?? '—'}`, meta: { label: 'Xe / tài xế' } }, { accessorKey: 'status', header: 'Trạng thái', cell: ({ getValue }) => scheduleStatusLabel(String(getValue())), meta: { label: 'Trạng thái' } }]
</script>
